-- ============================================================
-- SEED EXT 5: Módulo 02 — Present Simple (ex 241-300) — FINAL
-- Consolidação: PS em todos os contextos acadêmicos TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: PS em abstracts e resumos
  (cid,51,241,'gap_fill','This paper _____ (investigate) the effects of urban green space on psychological well-being in high-density residential areas.','investigates',NULL,'Abstract PS: ''this paper investigates'' = present simple for paper''s aims.','easy'),
  (cid,51,242,'gap_fill','The findings _____ (suggest) that exposure to natural environments _____ (significantly/reduce) cortisol levels.','suggest / significantly reduces',NULL,'Abstract PS: ''findings suggest'' + ''reduces'' for reported result.','easy'),
  (cid,51,243,'multiple_choice','Which sequence of tenses is CORRECT for an academic abstract?','This study examines X. Participants completed Y. Results indicate Z. The discussion considers W.','["This study examined X. Participants are completing Y. Results will indicate Z.","This study examines X. Participants completed Y. Results indicate Z. The discussion considers W.","This study will examine X. Participants completed Y. Results indicated Z.","This study examined X. Participants complete Y. Results are indicating Z."]','Abstract: PS for aims/findings; PS or past for methods; PS for conclusions.','hard'),
  (cid,51,244,'gap_fill','The article _____ (conclude) that stricter regulation is necessary and _____ (call) for immediate legislative action.','concludes / calls',NULL,'Abstract PS: ''the article concludes / calls for'' = meta-discourse verbs.','easy'),
  (cid,51,245,'gap_fill','The analysis _____ (reveal) three distinct clusters of behavior that _____ (correspond) to different levels of institutional trust.','reveals / correspond',NULL,'Results section PS for reporting patterns.','medium'),

  -- BLOCK 52: PS em introduções
  (cid,52,246,'gap_fill','Climate change _____ (pose) an unprecedented challenge to global food systems, particularly in regions that already _____ (face) water stress.','poses / face',NULL,'Introduction PS for current ongoing challenges (established fact).','easy'),
  (cid,52,247,'gap_fill','Despite growing awareness, policy responses _____ (remain) fragmented and _____ (fall) short of what the science _____ (recommend).','remain / fall / recommends',NULL,'PS for ongoing situation in introduction.','medium'),
  (cid,52,248,'multiple_choice','Why is present simple preferred for the background section of a research paper?','Because it describes a situation that is currently true and ongoing.','["Because papers are always written in the present","Because past events require present tense","Because it describes a situation that is currently true and ongoing.","Because it is less formal than other tenses"]','PS in introductions = states the current state of affairs that the research addresses.','medium'),
  (cid,52,249,'gap_fill','This paper _____ (address) this gap by _____ (provide) the first large-scale empirical analysis of the phenomenon.','addresses / providing',NULL,'''This paper addresses'' = PS + ''by + -ing'' = gerund for method.','medium'),

  -- BLOCK 53: PS com passivo presente
  (cid,53,250,'gap_fill','In most OECD countries, education policy _____ (determine/passive) at the national level, though implementation _____ (delegate/passive) to regional authorities.','is determined / is delegated',NULL,'PS passive for institutional arrangements.','medium'),
  (cid,53,251,'gap_fill','The relationship between poverty and academic achievement _____ (mediate/passive) by several factors, including access to nutritious food and healthcare.','is mediated',NULL,'PS passive for academic causal relationships.','hard'),
  (cid,53,252,'gap_fill','These findings _____ (report/passive) with appropriate caveats, as the sample _____ (not/represent/passive) the full diversity of the population.','are reported / is not fully represented',NULL,'PS passive for research limitations.','hard'),
  (cid,53,253,'multiple_choice','Which sentence correctly uses present simple passive in an academic context?','Quantitative methods are typically used when the research aims to establish causal relationships.','["Quantitative methods are typically using when research aims to establish causal relationships.","Quantitative methods were used when the research aims to establish causal relationships.","Quantitative methods are typically used when the research aims to establish causal relationships.","Quantitative methods are typically been used when research aims to establish causal relationships."]','''Are used'' = present simple passive for general methodological practice.','medium'),

  -- BLOCK 54: consolidação TOEFL Reading + PS
  (cid,54,254,'multiple_choice','[TOEFL Reading] ''The text suggests that access to education fundamentally shapes long-term economic outcomes.'' The verb ''suggests'' is in present simple because:','It describes what the text permanently ''says'' — the literary/academic present.','["The text is being read right now","It describes what the text permanently ''says'' — the literary/academic present.","The finding is hypothetical","The author is currently revising"]','Literary/academic present: the text perpetually ''suggests.''','easy'),
  (cid,54,255,'gap_fill','[TOEFL Reading] ''Economic theory _____ (predict) that as supply increases, prices _____ (fall).'' Best forms?','predicts / fall',NULL,'PS for economic theory/law (universal principle).','easy'),
  (cid,54,256,'multiple_choice','[TOEFL Reading] A sentence reads: ''Proponents of the theory argue that X; critics contend that Y.'' The present simple in both verbs signals:','An ongoing academic debate with active participants on both sides.','["A historical argument that is now resolved","An ongoing academic debate with active participants on both sides.","A universal scientific truth","A quotation from a specific source"]','PS for describing current academic debates.','medium'),
  (cid,54,257,'gap_fill','[TOEFL Reading] ''This _____ (apply) equally to economies that _____ (depend) primarily on natural resources and those that _____ (operate) manufacturing-led growth models.'' Best forms?','applies / depend / operate',NULL,'PS for general academic claim about all cases.','easy'),

  -- BLOCK 55: TOEFL Speaking — PS em tarefa integrada
  (cid,55,258,'production','[TOEFL Speaking — 45s] Summarize a reading about how the human brain processes language. Use present simple for scientific facts, literary present for what the reading says, and passive present for passive processes.','',NULL,'The reading explains that language processing in the human brain is distributed across multiple regions rather than localized in a single area. Broca''s area, located in the left frontal lobe, plays a key role in speech production, while Wernicke''s area, situated in the temporal lobe, is primarily associated with language comprehension. The reading notes that these areas are connected by a bundle of nerve fibers known as the arcuate fasciculus, and that damage to this connection disrupts the ability to repeat spoken language even when production and comprehension remain largely intact. Modern neuroimaging research suggests that the traditional two-region model significantly underestimates the complexity of language processing, which involves networks that extend across much of the cortex.','hard'),
  (cid,55,259,'production','[TOEFL Speaking — 45s] Explain what economics teaches us about incentives. Use present simple for general truths, stative verbs, and academic negatives.','',NULL,'Economics teaches us that incentives fundamentally shape human behavior. When the cost of an action falls, people tend to do more of it; when the benefit increases, demand rises. This principle applies not only to market behavior but to any domain where agents make choices under constraints. The theory of rational choice does not claim that people are perfectly rational; it suggests, more modestly, that people generally respond systematically to changes in the costs and benefits they face. Tax policy, for example, relies on this insight: governments impose taxes on activities they wish to discourage and offer subsidies for activities they wish to promote. Economic analysis does not determine which outcomes are desirable — that involves value judgments — but it does clarify the likely consequences of different policy choices.','hard'),

  -- BLOCK 56: TOEFL Writing — PS em essay completo
  (cid,56,260,'production','[TOEFL Writing — Introduction] Write a 100-word TOEFL essay introduction on ''Whether cities should ban private cars'' using PS throughout.','',NULL,'The role of private cars in urban environments generates significant debate among planners, economists, and citizens. Cars dominate most major cities'' physical space, produce a substantial share of urban air pollution, and contribute to congestion that reduces economic productivity and quality of life. Some urban theorists argue that banning private vehicles from city centers is not only feasible but desirable, pointing to successful examples in Oslo, Amsterdam, and Pontevedra. Critics counter that car restrictions penalize lower-income workers who depend on vehicles for employment. This essay argues that the evidence strongly supports phased restrictions on private cars in urban centers, provided that affordable and accessible alternatives are developed simultaneously.','hard'),
  (cid,56,261,'production','[TOEFL Writing — Body] Write a 100-word body paragraph arguing FOR banning private cars, using PS for general facts, passive PS, and academic connectors.','',NULL,'Urban areas that restrict private car access consistently demonstrate improvements in air quality, pedestrian safety, and public space quality. When private vehicles are removed from city centers, streets are reclaimed for cycling infrastructure, public seating, and green space, transforming environments that were previously dominated by noise and exhaust. Research consistently shows that cities with lower car dependency tend to have higher rates of physical activity among residents, which in turn reduces the prevalence of cardiovascular disease and obesity. The economic costs of congestion are significant: traffic delays cost major metropolitan economies billions of dollars annually in lost productivity. These costs are externalized onto the public, while the benefits of car use accrue privately.','hard'),
  (cid,56,262,'production','[TOEFL Writing — Counterargument] Write a 100-word counterargument paragraph on car bans, using PS and appropriate concessive connectors.','',NULL,'Critics of private car bans rightly note that public transportation networks in many cities do not yet serve all areas adequately, meaning that restrictions disproportionately affect workers in peripheral neighborhoods who currently lack viable alternatives. For lower-income residents, a private car often represents the difference between employment and unemployment — particularly for those who work irregular hours when public transit runs infrequently. Blanket bans without concurrent investment in affordable, frequent, and geographically comprehensive transit risk widening rather than narrowing existing social inequalities. The policy is therefore not inherently wrong, but its implementation requires careful attention to equity, and timeline flexibility that allows transit infrastructure to develop before restrictions take effect.','hard'),
  (cid,56,263,'production','[TOEFL Writing — Conclusion] Write a 75-word conclusion for the car ban essay using PS.','',NULL,'The evidence suggests that restricting private car access in urban centers improves environmental, public health, and quality-of-life outcomes, but only when implemented alongside high-quality public transit investment. Cities that pursue car restrictions without addressing transit equity risk undermining the broader social goals that the policy is intended to serve. The question is therefore not whether to limit private cars, but how to sequence the transition in ways that leave no community behind.','medium'),

  -- BLOCK 57: mixed review final
  (cid,57,264,'multiple_choice','Which sentence uses the WRONG tense for a TOEFL essay thesis statement?','The study examined three factors that explained the variance in academic performance.','["This essay argues that economic growth and environmental sustainability can coexist (correct PS).","The evidence clearly suggests that early intervention produces better outcomes (correct PS).","The study examined three factors that explained the variance in academic performance.","These findings indicate that a more nuanced approach is required (correct PS)."]','Thesis in a TOEFL essay = present simple. Past simple is for describing specific studies.','medium'),
  (cid,57,265,'gap_fill','The gap between what the research _____ (demonstrate) and what policymakers _____ (actually/implement) _____ (remain) a central challenge for applied social science.','demonstrates / actually implement / remains',NULL,'PS for general academic observation about theory-practice gap.','medium'),
  (cid,57,266,'gap_fill','This essay _____ (not/claim) that technology is inherently good or bad; it _____ (simply/argue) that context _____ (determine) outcomes.','does not claim / simply argues / determines',NULL,'PS negative + PS positive for thesis nuancing.','medium'),
  (cid,57,267,'multiple_choice','Which TOEFL essay sentence BEST uses present simple for a sophisticated claim?','Contemporary neuroscience increasingly suggests that the traditional dichotomy between emotion and reason does not accurately describe how the human brain processes information and makes decisions.','["Contemporary neuroscience increasingly suggested that the dichotomy does not accurately describe.","Contemporary neuroscience increasingly suggests that the traditional dichotomy between emotion and reason does not accurately describe how the human brain processes information and makes decisions.","Contemporary neuroscience has increasingly suggested that the dichotomy did not accurately describe.","Contemporary neuroscience is increasingly suggesting that the dichotomy does not accurately describe."]','PS for current academic field position (stable, established scholarly view).','hard'),

  -- BLOCK 58: últimos exercícios de fechamento
  (cid,58,268,'gap_fill','Access to quality education _____ (not/guarantee) upward mobility, but its absence _____ (significantly/reduce) the probability of achieving it.','does not guarantee / significantly reduces',NULL,'PS negative + PS positive for nuanced claim.','medium'),
  (cid,58,269,'production','[TOEFL Writing — 200 words] Write a final consolidation paragraph on globalization and cultural identity using PS: present simple active, present simple passive, stative verbs, frequency adverbs, literary present (citing a theorist), and academic negative.','',NULL,'Globalization exerts complex and often contradictory pressures on cultural identity. On one hand, the global circulation of media, products, and ideas exposes individuals to a far wider range of cultural influences than any previous generation encountered. On the other hand, this exposure does not necessarily homogenize culture: sociologists such as Stuart Hall argue that cultures do not passively absorb external influences but actively negotiate them, producing hybrid identities that simultaneously incorporate global elements and assert local distinctiveness. The evidence consistently suggests that predictions of cultural uniformity — a global monoculture driven by American media dominance — have not materialized in the form that early critics feared. Regional languages, culinary traditions, and artistic forms are frequently revitalized rather than erased by contact with global flows, particularly when local communities retain the institutional and economic resources to sustain cultural production. That said, power asymmetries in the global cultural economy are real: the capacity to produce and distribute culture at scale is not evenly distributed, and smaller cultural economies are genuinely vulnerable to displacement.','hard'),
  (cid,58,270,'production','[TOEFL Writing — 200 words] Write a body paragraph on ''Universal healthcare as a public good'' using: PS for general truths, stative verbs (constitute, represent, involve, require), frequency adverbs, and academic passive PS.','',NULL,'Healthcare constitutes a public good in the classical economic sense when its provision generates benefits that extend beyond the individual receiving treatment. A vaccinated population, for example, protects not only the individuals vaccinated but the wider community through herd immunity — benefits that are not captured in any private transaction. Healthcare systems also represent a form of risk pooling: individuals cannot reliably predict when they will require expensive medical intervention, and markets characteristically fail to provide affordable insurance to those most likely to need it. Consequently, healthcare is typically organized at a social rather than a market level in countries that achieve the best outcomes. Evidence consistently suggests that systems in which universal coverage is mandated achieve better population-level health metrics at lower per-capita cost than those in which access is primarily determined by ability to pay. This pattern is observed across economies of widely different structures and income levels, which strongly suggests that the design of the healthcare system — rather than national wealth alone — determines outcomes. Universal healthcare does not require uniformity of provision; it requires only that no one is excluded from necessary care on grounds of cost.','hard'),

  (cid,58,271,'multiple_choice','Final: Which set of academic verbs ALL take present simple (not continuous) in academic writing?','Suggest, indicate, demonstrate, argue, show, reveal, appear, seem, contain, consist of.','["Suggest, indicate, demonstrate, argue, show, reveal, appear, seem, contain, consist of.","Suggest, indicate, are demonstrating, arguing, showing, reveal, seem, contain, consist of.","Suggest, indicate, demonstrate, argue, show, are revealing, appear, seem, containing, consist of.","Suggest, indicate, demonstrate, argue, show, reveal, appear, seem, are containing, are consisting of."]','All key academic reporting and stative verbs use present simple, not continuous.','medium'),
  (cid,58,272,'gap_fill','Scientific consensus _____ (not/emerge) overnight; it _____ (develop) gradually as evidence _____ (accumulate) and _____ (critically/evaluate/passive).','does not emerge / develops / accumulates / is critically evaluated',NULL,'PS chain for describing scientific process.','hard'),
  (cid,58,273,'production','[TOEFL Writing — 200 words] Integrated essay paragraph: A reading argues that microfinance reduces poverty. A lecture challenges this, arguing that evidence is mixed. Report both positions using present simple, literary present, and academic negatives.','',NULL,'The reading presents microfinance — the provision of small loans to low-income entrepreneurs — as a powerful tool for poverty reduction. The author argues that access to capital enables small-scale business development that would otherwise be impossible for individuals excluded from formal banking systems. The reading cites Muhammad Yunus, who maintains in his foundational work that credit is a human right and that small-scale entrepreneurship, when adequately funded, generates a self-sustaining cycle of economic empowerment. The lecture, however, challenges the empirical basis of this optimism. The professor notes that rigorous randomized controlled trials conducted over the past fifteen years do not consistently demonstrate that microfinance significantly reduces poverty or improves long-term well-being. She does not argue that microfinance is without value — it may provide useful financial services to underserved populations — but she contends that it does not constitute the transformative poverty-reduction mechanism that its strongest advocates suggest. The lecture thus represents a broader pattern in development economics: interventions that appear compelling in theory and in small-scale pilots do not always produce the same results when evaluated rigorously and at scale.','hard'),

  (cid,58,274,'gap_fill','This review _____ (not/pretend) to be comprehensive; it _____ (instead/focus) on the most methodologically rigorous studies that _____ (directly/address) the research question.','does not pretend / instead focuses / directly address',NULL,'PS scope limitation in academic review paper.','medium'),
  (cid,58,275,'production','[TOEFL Writing — 200 words] Final task: Write a body paragraph on artificial intelligence and employment. Use: PS (5+), passive PS (2+), stative verbs (2+), frequency adverbs (2+), academic negative (1+), hedged claim with may/might (1+).','',NULL,'Artificial intelligence and automation increasingly affect the nature of work across virtually all sectors of the economy. Routine cognitive and manual tasks are systematically replaced by algorithmic systems that execute them more cheaply and reliably than human workers. Research consistently suggests that this process primarily displaces middle-skill employment — the clerical, administrative, and manufacturing roles that historically supported a broad middle class — while simultaneously increasing demand for both high-skill analytical work and low-skill personal service jobs that are currently difficult to automate. This pattern is sometimes described as ''labor market polarization,'' and it is observed across all major economies regardless of their industrial structure. The net employment effects of AI adoption remain contested: some economists argue that historical technological transitions have always created more jobs than they destroy, and that the current wave does not represent a fundamental departure from this pattern. Others contend that the pace and breadth of AI-driven displacement may be qualitatively different from previous technological transitions and may overwhelm the economy''s capacity to create new roles quickly enough. What seems clear is that the distributional consequences of AI adoption — who benefits and who loses — are not automatically favorable and require deliberate policy attention.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
